import json
import re
from docx import Document

def fill_template(template_path, data_path, output_path):
    # Load data
    with open(data_path, 'r') as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    relocation_enabled = data.get('RELOCATION_PACKAGE') == 'Yes'

    def replace_in_para(para, data):
        text = para.text
        # Handle conditional markers first if they are in the same paragraph
        if '{{IF_RELOCATION}}' in text or '{{END_IF_RELOCATION}}' in text:
            text = text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')

        # Replace other placeholders
        pattern = r'\{\{([A-Z_]+)\}\}'
        if not re.search(pattern, text):
            if text != para.text: # If we removed markers
                if para.runs:
                    para.runs[0].text = text
                    for run in para.runs[1:]:
                        run.text = ''
            return

        new_text = text
        for match in re.finditer(pattern, text):
            key = match.group(1)
            placeholder = match.group(0)
            if key in data:
                new_text = new_text.replace(placeholder, str(data[key]))

        if new_text != para.text:
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.text = new_text

    # First pass: Handle relocation block removal if not enabled
    if not relocation_enabled:
        in_block = False
        paras_to_remove = []
        for para in doc.paragraphs:
            if '{{IF_RELOCATION}}' in para.text:
                in_block = True
                paras_to_remove.append(para)
                continue
            if '{{END_IF_RELOCATION}}' in para.text:
                in_block = False
                paras_to_remove.append(para)
                continue
            if in_block:
                paras_to_remove.append(para)

        for para in paras_to_remove:
            p = para._element
            p.getparent().remove(p)
            p._p = p._element = None

    # Second pass: Replace placeholders in all remaining parts
    for para in doc.paragraphs:
        replace_in_para(para, data)

    # Tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_para(para, data)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # Headers/Footers
    for section in doc.sections:
        for para in section.header.paragraphs:
            replace_in_para(para, data)
        for para in section.footer.paragraphs:
            replace_in_para(para, data)

    doc.save(output_path)

if __name__ == "__main__":
    fill_template('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')

